// Tilemap preview renderer. Artwork is generated by image_gen; source PNGs are never rewritten.
// Large background sprites overlap like shader-blended tiles. Foreground uses the existing v8 atlas.
const fs=require('node:fs'),path=require('node:path'),assert=require('node:assert/strict');
let sharp;try{sharp=require('sharp')}catch{sharp=require(path.join(process.env.USERPROFILE,'.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/sharp'))}
const root=__dirname,spec=JSON.parse(fs.readFileSync(path.join(root,'design.json'))),W=spec.canvas.width,H=spec.canvas.height;
const smooth=t=>(t=Math.max(0,Math.min(1,t)),t*t*(3-2*t));
const hash=(x,y)=>{let n=Math.imul(x+37,374761393)^Math.imul(y+71,668265263);n=Math.imul(n^(n>>>13),1274126177);return(n^(n>>>16))>>>0};
const luma=(r,g,b)=>r*.2126+g*.7152+b*.0722;
async function loadBackground(file){return sharp(path.join(root,'tiles',file)).resize(spec.background.renderTileSize,spec.background.renderTileSize).ensureAlpha().raw().toBuffer()}
function tilePlacement(col,row){const h=hash(col,row);return {col,row,x:col*spec.background.stride,y:row*spec.background.stride,flipX:!!(h&1),flipY:!!(h&2)}}
function backgroundPixel(texture,x,y){
 const {renderTileSize:n,stride,overlap,airColor:air,opacity}=spec.background;
 const col=Math.floor(x/stride),row=Math.floor(y/stride),sum=[0,0,0];let weight=0;
 for(let cy=row-1;cy<=row;cy++)for(let cx=col-1;cx<=col;cx++){
  const p=tilePlacement(cx,cy),lx=x-p.x,ly=y-p.y;if(lx<0||ly<0||lx>=n||ly>=n)continue;
  const w=smooth(lx/overlap)*smooth((n-1-lx)/overlap)*smooth(ly/overlap)*smooth((n-1-ly)/overlap);
  const tx=p.flipX?n-1-lx:lx,ty=p.flipY?n-1-ly:ly,i=(ty*n+tx)*4,a=texture[i+3]/255*opacity;
  for(let c=0;c<3;c++)sum[c]+=(air[c]*(1-a)+texture[i+c]*a)*w;weight+=w;
 }
 assert(weight>0,'Background tile coverage');return sum.map(v=>v/weight);
}
async function loadTerrain(region,layout){
 const folder=path.resolve(root,spec.terrain.source,region.terrainFolder),map=JSON.parse(fs.readFileSync(path.join(folder,layout+'-tilemap.json')));
 const {data,info}=await sharp(path.join(folder,map.atlas)).ensureAlpha().raw().toBuffer({resolveWithObject:true});
 return {map,data,width:info.width};
}
function terrainPixel(t,x,y){
 const n=t.map.tileSize,col=Math.floor(x/n),row=Math.floor(y/n);if(col<0||row<0||col>=t.map.width||row>=t.map.height)return [0,0,0,0];
 const id=t.map.cells[row*t.map.width+col];if(id<0)return [0,0,0,0];
 const sx=id%t.map.atlasColumns*n+x%n,sy=Math.floor(id/t.map.atlasColumns)*n+y%n,i=(sy*t.width+sx)*4;
 return [t.data[i],t.data[i+1],t.data[i+2],t.data[i+3]];
}
async function main(){
 const loaded={};for(const r of spec.regions)loaded[r.id]={region:r,background:await loadBackground(r.file)};
 const results=[];fs.mkdirSync(path.join(root,'previews'),{recursive:true});
 for(const p of spec.previews){
  const zones=p.zones.map(id=>loaded[id]),terrain=await Promise.all(zones.map(z=>loadTerrain(z.region,p.layout)));
  const output=Buffer.alloc(W*H*4),bgOnly=Buffer.alloc(W*H*3);let bgLum=0,bgCount=0,edgeLum=0,edgeCount=0;
  for(let y=0;y<H;y++)for(let x=0;x<W;x++){
   const t=zones.length===2?smooth((x-spec.transition.startX)/(spec.transition.endX-spec.transition.startX)):0;
   const bg0=backgroundPixel(zones[0].background,x+237,y+173),bg1=t?backgroundPixel(zones[1].background,x+237,y+173):bg0;
   const bg=bg0.map((v,c)=>v*(1-t)+bg1[c]*t),i=(y*W+x)*4,bi=(y*W+x)*3;
   const ty=y-spec.canvas.terrainOffsetY,a=terrainPixel(terrain[0],x+p.cropX,ty),b=t?terrainPixel(terrain[1],x+p.cropX,ty):a;
   // Premultiplied sprite blending, as in a terrain transition shader.
   const aa=a[3]/255,ba=b[3]/255,alpha=aa*(1-t)+ba*t;
   for(let c=0;c<3;c++){bgOnly[bi+c]=Math.round(bg[c]);output[i+c]=Math.round(bg[c]*(1-alpha)+a[c]*aa*(1-t)+b[c]*ba*t)}output[i+3]=255;
   if(alpha<.01){bgLum+=luma(...bg);bgCount++}
   if(alpha>.99&&ty>=384&&ty<408){edgeLum+=luma(output[i],output[i+1],output[i+2]);edgeCount++}
  }
  const filename=p.id+'-'+p.zones.join('-')+'-with-ground.png';await sharp(output,{raw:{width:W,height:H,channels:4}}).png().toFile(path.join(root,'previews',filename));
  const placements=[];for(let row=-1;row<=2;row++)for(let col=-1;col<=3;col++){
   const placement=tilePlacement(col,row),n=spec.background.renderTileSize;
   if(placement.x+n>237&&placement.x<237+W&&placement.y+n>173&&placement.y<173+H)placements.push(placement);
  }
  fs.writeFileSync(path.join(root,'previews',p.id+'-layout.json'),JSON.stringify({canvas:spec.canvas,background:{zones:p.zones,tileSize:1024,overlap:256,viewOffset:[237,173],placements},foreground:{layout:p.layout,cropX:p.cropX,source:p.zones.map(id=>loaded[id].region.terrainFolder)},transition:p.zones.length===2?spec.transition:null},null,2)+'\n');
  // A painted material can have a legitimate sharp fleck at a boundary. Compare the
  // whole seam with nearby scanlines so texture detail is not mistaken for a tile join.
  const seams=[];for(const axis of ['x','y'])for(let pos=0;pos<(axis==='x'?W:H);pos++)if((pos+(axis==='x'?237:173))%spec.background.stride===0){
   const scan=q=>{const values=[];for(let k=0;k<(axis==='x'?H:W);k++){const x=axis==='x'?q:k,y=axis==='y'?q:k;if(x<=0||y<=0||x>=W||y>=H)continue;
    const i=(y*W+x)*3,j=axis==='x'?i-3:i-W*3;for(let c=0;c<3;c++)values.push(Math.abs(bgOnly[i+c]-bgOnly[j+c]));}return values};
   const values=scan(pos).sort((a,b)=>a-b),nearby=[-8,-4,4,8].flatMap(offset=>scan(pos+offset));
   seams.push({axis,position:pos,maxAdjacentChannelDifference:values.at(-1),p95AdjacentChannelDifference:values[Math.floor(values.length*.95)],meanAdjacentChannelDifference:values.reduce((a,b)=>a+b,0)/values.length,nearbyMeanDifference:nearby.reduce((a,b)=>a+b,0)/nearby.length});
  }
  const result={file:filename,zones:p.zones,backgroundTileInstances:placements.length,backgroundMeanLuminance:bgLum/bgCount,terrainEdgeMeanLuminance:edgeLum/edgeCount,seams};
  assert(result.backgroundMeanLuminance<60,'Background must recede');assert(seams.every(s=>s.meanAdjacentChannelDifference<=Math.max(3,s.nearbyMeanDifference*1.75)&&s.p95AdjacentChannelDifference<=12),'Visible tile boundary discontinuity');
  results.push(result);console.log(JSON.stringify(result));
 }
 fs.writeFileSync(path.join(root,'validation.json'),JSON.stringify({status:'passed',previewCount:results.length,renderSize:[W,H],rawSourceFilesUnchanged:true,hardEdgeSeamless:false,connection:'256px overlapping large sprites with smooth normalized weights',unityApplied:false,results},null,2)+'\n');
}
main().catch(e=>{console.error(e);process.exitCode=1});
